54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Dedicated audit logger; a successful create emits one line here. */
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
70	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
113	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
114	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        HttpHeaders headers = new HttpHeaders();
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        String address = normalizeAddress(owner.getAddress());
123	        if (address.isEmpty()) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        owner.setAddress(address);
127	        if (owner.getEmail() != null) {
128	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
129	            if (!EMAIL_PATTERN.matcher(email).matches()) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email);
133	        }
134	        String telephone = normalizeTelephone(owner.getTelephone());
135	        if (telephone == null) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        owner.setTelephone(telephone);
139	        LocalDate registrationDate = resolveRegistrationDate(owner.getRegistrationDate());
140	        owner.setRegistrationDate(registrationDate);
141	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
142	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
143	        }
144	        if (isTelephoneInUse(telephone)) {
145	            return new ResponseEntity<>(HttpStatus.CONFLICT);
146	        }
147	        if (owner.getEmail() != null && isEmailInUse(owner.getEmail())) {
148	            return new ResponseEntity<>(HttpStatus.CONFLICT);
149	        }
150	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && isHouseholdInUse(owner)) {
151	            return new ResponseEntity<>(HttpStatus.CONFLICT);
152	        }
153	        if (countOwnersInCity(owner.getCity()) >= 50) {
154	            return new ResponseEntity<>(HttpStatus.CONFLICT);
155	        }
156	        assignRegistrationAttributes(owner);
157	        this.clinicService.saveOwner(owner);
158	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
159	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
160	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
161	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
162	        headers.setLocation(UriComponentsBuilder.newInstance()
163	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
164	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
170	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
171	        if (currentOwner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        currentOwner.setAddress(ownerFieldsDto.getAddress());
175	        currentOwner.setCity(ownerFieldsDto.getCity());
176	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
177	        currentOwner.setLastName(ownerFieldsDto.getLastName());
178	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
179	        String email = ownerFieldsDto.getEmail();
180	        if (email != null) {
181	            email = email.trim().toLowerCase(Locale.ROOT);
182	            if (!EMAIL_PATTERN.matcher(email).matches()) {
183	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	            }
185	        }
186	        currentOwner.setEmail(email);
187	        this.clinicService.saveOwner(currentOwner);
188	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Transactional
193	    @Override
194	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
195	        Owner owner = this.clinicService.findOwnerById(ownerId);
196	        if (owner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        this.clinicService.deleteOwner(owner);
200	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
206	        Owner owner = this.clinicService.findOwnerById(ownerId);
207	        if (owner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        HttpHeaders headers = new HttpHeaders();
211	        Pet pet = petMapper.toPet(petFieldsDto);
212	        owner.setId(ownerId);
213	        pet.setOwner(owner);
214	        pet.getType().setName(null);
215	        this.clinicService.savePet(pet);
216	        PetDto petDto = petMapper.toPetDto(pet);
217	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
218	            .buildAndExpand(pet.getId()).toUri());
219	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
220	    }
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
225	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
226	        if (currentOwner != null) {
227	            Pet currentPet = this.clinicService.findPetById(petId);
228	            if (currentPet != null) {
229	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
230	                currentPet.setName(petFieldsDto.getName());
231	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
232	                this.clinicService.savePet(currentPet);
233	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
234	            }
235	        }
236	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	    }
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
242	        HttpHeaders headers = new HttpHeaders();
243	        Visit visit = visitMapper.toVisit(visitFieldsDto);
244	        Pet pet = new Pet();
245	        pet.setId(petId);
246	        visit.setPet(pet);
247	        this.clinicService.saveVisit(visit);
248	        VisitDto visitDto = visitMapper.toVisitDto(visit);
249	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
250	            .buildAndExpand(visit.getId()).toUri());
251	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
252	    }
253	
254	
255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Override
257	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
258	        Owner owner = this.clinicService.findOwnerById(ownerId);
259	        if (owner != null) {
260	            Pet pet = owner.getPet(petId);
261	            if (pet != null) {
262	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
263	            }
264	        }
265	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	    }
267	
268	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
269	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
270	
271	    /**
272	     * Required national-number length per country code: '+61' (Australia) expects 9 national
273	     * digits and '+1' (NANP) expects 10. A number whose country code is listed here but whose
274	     * national part is not the required length is rejected.
275	     */
276	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
277	        "+61", 9, "+1", 10);
278	
279	    /**
280	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
281	     * code are kept when present; otherwise country code '+61' is assumed and a single
282	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
283	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
284	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
285	     * Returns {@code null} when the number cannot form a valid E.164 value.
286	     */
287	    private static String normalizeTelephone(String telephone) {
288	        if (telephone == null) {
289	            return null;
290	        }
291	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
292	        String e164;
293	        if (cleaned.startsWith("+")) {
294	            e164 = cleaned;
295	        } else {
296	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
297	            e164 = "+61" + national;
298	        }
299	        if (!E164_PATTERN.matcher(e164).matches()) {
300	            return null;
301	        }
302	        return hasValidNationalNumberLength(e164) ? e164 : null;
303	    }
304	
305	    /**
306	     * Whether the national number of a well-formed E.164 value has the length required for its
307	     * country code. Country codes not listed in {@link #NATIONAL_NUMBER_LENGTHS} carry no
308	     * per-country length rule and are accepted.
309	     */
310	    private static boolean hasValidNationalNumberLength(String e164) {
311	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
312	            String countryCode = entry.getKey();
313	            if (e164.startsWith(countryCode)) {
314	                return e164.length() - countryCode.length() == entry.getValue();
315	            }
316	        }
317	        return true;
318	    }
319	
320	    /**
321	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
322	     * code, membership number, household id, namesake count and household member count. Each is
323	     * derived from the owner's already-normalized fields and the existing owner population, so this
324	     * must run before the owner is saved, while the counts still exclude the owner being created.
325	     */
326	    private void assignRegistrationAttributes(Owner owner) {
327	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
328	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
329	        owner.setHouseholdId(householdId(owner));
330	        owner.setNamesakeCount(countNamesakes(owner));
331	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
332	    }
333	
334	    /**
335	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
336	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
337	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
338	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
339	     */
340	    private String generateCustomerCode(String city, String lastName) {
341	        String city3 = firstThreeLetters(city);
342	        String last3 = firstThreeLetters(lastName);
343	        int sequence = countOwnersInCity(city) + 1;
344	        return String.format("%s-%s-%04d", city3, last3, sequence);
345	    }
346	
347	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
348	    private static String firstThreeLetters(String value) {
349	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
350	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
351	    }
352	
353	    /**
354	     * The number of existing owners registered in {@code city}, compared case-insensitively
355	     * with collapsed whitespace.
356	     */
357	    private int countOwnersInCity(String city) {
358	        String normalized = normalizeHouseholdField(city);
359	        return (int) this.clinicService.findAllOwners().stream()
360	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
361	            .count();
362	    }
363	
364	    /**
365	     * The effective registration date to store for a new owner: the date supplied on the request
366	     * when present, otherwise the current server date, in either case rolled forward to a business
367	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
368	     * This single point of resolution is what every registration-date-derived value (the stored
369	     * date, the membership number's year segment, the per-day create-limit) is computed from.
370	     */
371	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
372	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
373	        return toBusinessDay(date);
374	    }
375	
376	    /**
377	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
378	     * following Monday; a weekday is returned unchanged.
379	     */
380	    private static LocalDate toBusinessDay(LocalDate date) {
381	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
382	            date = date.plusDays(1);
383	        }
384	        return date;
385	    }
386	
387	    /**
388	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
389	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
390	     */
391	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
392	        String yy = String.format("%02d", registrationDate.getYear() % 100);
393	        return customerCode + "-M" + yy;
394	    }
395	
396	    /**
397	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
398	     * last name, compared case-insensitively.
399	     */
400	    private int countNamesakes(Owner owner) {
401	        String firstName = normalizeHouseholdField(owner.getFirstName());
402	        String lastName = normalizeHouseholdField(owner.getLastName());
403	        return (int) this.clinicService.findAllOwners().stream()
404	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
405	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
406	            .count();
407	    }
408	
409	    /**
410	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
411	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
412	     * unusually high daily signup volume.
413	     */
414	    private boolean isBulkSignupWarning() {
415	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
416	    }
417	
418	    /** The number of existing owners whose registration date is {@code date}. */
419	    private int countOwnersRegisteredOn(LocalDate date) {
420	        return (int) this.clinicService.findAllOwners().stream()
421	            .filter(existing -> date.equals(existing.getRegistrationDate()))
422	            .count();
423	    }
424	
425	    /** Whether any existing owner already uses the given (E.164) telephone number. */
426	    private boolean isTelephoneInUse(String telephone) {
427	        return this.clinicService.findAllOwners().stream()
428	            .map(Owner::getTelephone)
429	            .filter(existing -> existing != null)
430	            .map(OwnerRestControllerV1::normalizeTelephone)
431	            .filter(existing -> existing != null)
432	            .anyMatch(telephone::equals);
433	    }
434	
435	    /** Whether any existing owner already uses the given email, compared case-insensitively (lower-cased). */
436	    private boolean isEmailInUse(String email) {
437	        String normalized = email.trim().toLowerCase(Locale.ROOT);
438	        return this.clinicService.findAllOwners().stream()
439	            .map(Owner::getEmail)
440	            .filter(existing -> existing != null)
441	            .map(existing -> existing.trim().toLowerCase(Locale.ROOT))
442	            .anyMatch(normalized::equals);
443	    }
444	
445	    /** Common street-type abbreviations expanded during address normalization. */
446	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
447	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
448	
449	    /**
450	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
451	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
452	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
453	     * string when {@code address} is null or blank after normalization.
454	     */
455	    private static String normalizeAddress(String address) {
456	        if (address == null) {
457	            return "";
458	        }
459	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
460	        if (collapsed.isEmpty()) {
461	            return "";
462	        }
463	        StringBuilder sb = new StringBuilder(collapsed.length());
464	        for (String token : collapsed.split(" ")) {
465	            if (sb.length() > 0) {
466	                sb.append(' ');
467	            }
468	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
469	        }
470	        return sb.toString();
471	    }
472	
473	    /**
474	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
475	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
476	     */
477	    private static String normalizeHouseholdField(String value) {
478	        if (value == null) {
479	            return "";
480	        }
481	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
482	    }
483	
484	    /**
485	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
486	     * same address compared case-insensitively with collapsed whitespace.
487	     */
488	    private List<Owner> findHousemates(Owner owner) {
489	        String lastName = normalizeHouseholdField(owner.getLastName());
490	        String address = normalizeHouseholdField(owner.getAddress());
491	        return this.clinicService.findAllOwners().stream()
492	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
493	                && normalizeHouseholdField(existing.getAddress()).equals(address))
494	            .toList();
495	    }
496	
497	    /**
498	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
499	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
500	     */
501	    private boolean isHouseholdInUse(Owner owner) {
502	        return !findHousemates(owner).isEmpty();
503	    }
504	
505	    /**
506	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
507	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
508	     */
509	    private int countHouseholdMembers(Owner owner) {
510	        return findHousemates(owner).size() + 1;
511	    }
512	
513	    /**
514	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
515	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
516	     * deterministically from those normalized fields so housemates always resolve to the same value,
517	     * regardless of registration order.
518	     */
519	    private static String householdId(Owner owner) {
520	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
521	            + normalizeHouseholdField(owner.getAddress());
522	        try {
523	            byte[] digest = MessageDigest.getInstance("SHA-256")
524	                .digest(key.getBytes(StandardCharsets.UTF_8));
525	            StringBuilder sb = new StringBuilder(24);
526	            for (int i = 0; i < 12; i++) {
527	                sb.append(String.format("%02X", digest[i]));
528	            }
529	            return sb.toString();
530	        }
531	        catch (NoSuchAlgorithmException e) {
532	            throw new IllegalStateException("SHA-256 not available", e);
533	        }
534	    }
535	}
