143	    public void setHouseholdMemberCount(Integer householdMemberCount) {
144	        this.householdMemberCount = householdMemberCount;
145	    }
146	
147	    public String getMembershipNumber() {
148	        return this.membershipNumber;
149	    }
150	
151	    public void setMembershipNumber(String membershipNumber) {
152	        this.membershipNumber = membershipNumber;
153	    }
154	
155	    /**
156	     * The owner's numeric membership level, derived on creation: it starts at 1, gains 1 when an
157	     * email is present, gains 1 when {@link #namesakeCount} is 0, and is capped at 3 (level 4 is
158	     * reserved for tenure).
159	     */
160	    @Transient
161	    public Integer getMembershipLevel() {
162	        int level = 1;
163	        if (this.email != null && !this.email.isBlank()) {
164	            level++;
165	        }
166	        if (this.namesakeCount != null && this.namesakeCount == 0) {
167	            level++;
168	        }
169	        return Math.min(level, 3);
170	    }
171	
172	    /**
173	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
174	     * present, otherwise {@code "PHONE"}.
175	     */
176	    @Transient
177	    public String getContactPreference() {
178	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
179	    }
180	
181	    protected Set<Pet> getPetsInternal() {
